      "ru": "Единственные сохранившиеся ворота городской стены Вильнюса с чудотворной иконой Остробрамской Божией Матери. Сакральное место для земель ВКЛ, воспетое Адамом Мицкевичем и Максимом Богдановичем («Погоня»).",
      "en": "The only remaining city gate of historical Vilnius, housing the revered icon of Our Lady of the Gate of Dawn. A major spiritual site deeply tied to Grand Duchy history and celebrated by poets Adam Mickiewicz and Maksim Bahdanovič."
