      "by": "Адрас:  Kauno, 7.\n\nУ будынку, дзе цяпер месціцца віленская бальніца ім. Марцінкявічуса, падчас Першай сусветнай вайны быў вайсковы шпіталь \"Мішмерас Хойлем\", дзе пасля вяртання з эміграцыі (1914) працавала беларускай дзеячка і літаратарка Цётка і лячыўся ад ранення класік айчыннай літаратуры Максім Гарэцкі.",
