    "description": {
      "by": "Адрас: Arklių, 18.\n\nЗ 1884 па 1898 год “айцец беларускай нацыянальнай ідэі” Францішак Багушэвічён правёў у зялёным дворыку пана Казлоўскага. На жаль дом, у якім Багушэвіч стварыў легендарныя паэтычныя зборнікі «Дудка беларуская» (Кракаў, 1891) і «Смык беларускі» (Познань, 1894), сфармуляваў асноватворныя прынцыпы нацыянальнай ідэалогіі, не датрываў да нашых дзён. Цяпер на яго месцы будынак Міжнароднай школы менеджмента. Менавіта тут у верасні 2010 адбылося адкрыццё мемарыяльнай шыльды ў гонар патрыярха беларускай літаратуры.",
      "ru": "Адрас: Arklių, 18.\n\nЗ 1884 па 1898 год “айцец беларускай нацыянальнай ідэі” Францішак Багушэвічён правёў у зялёным дворыку пана Казлоўскага. На жаль дом, у якім Багушэвіч стварыў легендарныя паэтычныя зборнікі «Дудка беларуская» (Кракаў, 1891) і «Смык беларускі» (Познань, 1894), сфармуляваў асноватворныя прынцыпы нацыянальнай ідэалогіі, не датрываў да нашых дзён. Цяпер на яго месцы будынак Міжнароднай школы менеджмента. Менавіта тут у верасні 2010 адбылося адкрыццё мемарыяльнай шыльды ў гонар патрыярха беларускай літаратуры.",
      "en": "Адрас: Arklių, 18.\n\nЗ 1884 па 1898 год “айцец беларускай нацыянальнай ідэі” Францішак Багушэвічён правёў у зялёным дворыку пана Казлоўскага. На жаль дом, у якім Багушэвіч стварыў легендарныя паэтычныя зборнікі «Дудка беларуская» (Кракаў, 1891) і «Смык беларускі» (Познань, 1894), сфармуляваў асноватворныя прынцыпы нацыянальнай ідэалогіі, не датрываў да нашых дзён. Цяпер на яго месцы будынак Міжнароднай школы менеджмента. Менавіта тут у верасні 2010 адбылося адкрыццё мемарыяльнай шыльды ў гонар патрыярха беларускай літаратуры."
    },
