    "description": {
      "by": "Адрас: Šv. Jono, 4.\n\nУ першай палове 17 ст. Мікалай Хрыстафор Радзівіл Сіротка перанёс сюды з Берасця друкарню езуіцкай акадэміі , якая была адной з найбуйнейшых у Рэчы Паспалітай. Паміж 1633 і 1752 гг. тут выдавалася ад 10 да 25 выданняў штогод, у тым ліку найкаштоўная навуковая літаратура ў Літве 18 ст. З варштатаў акадэмічнай друкарні выходзіла першая газета гістарычнай Літвы — “Kuryer Litewski”. \n\nПасля ліквідацыі Ордэну іезуітаў (1773) друкарня адышла да Віленскага ўніверсітэта, які ў 1805 годзе прадаў яе выдаўцу Юзэфу Завадскаму. Апроч іншага тут друкаваліся газеты “Dziennik Wileński”, “Pamiętnik Towarzystwa Liekarskiego Wileńskiego”, а ў 1822 годзе ўбачыў свет першы зборнік Адама Міцкевіча “Ballady i romanse”. Пра гэта сёння нагадвае мемарыяльная дошка (1999). \n\nСледам за Завадскім тут гаспадарыў выдавец Мікалай Глюксберг (да сярэдзіны 19 ст.), у якога друкаваліся гістарычны часопіс Юзафа Крашэўскага “Atheneum“ і альманах Адама Кіркора “Teka Wileńska”.\n\nЦяпер двухпавярховы дом займаюць памяшканні бібліятэк Віленскага ўніверсітэту.",
      "ru": "Адрас: Šv. Jono, 4.\n\nУ першай палове 17 ст. Мікалай Хрыстафор Радзівіл Сіротка перанёс сюды з Берасця друкарню езуіцкай акадэміі , якая была адной з найбуйнейшых у Рэчы Паспалітай. Паміж 1633 і 1752 гг. тут выдавалася ад 10 да 25 выданняў штогод, у тым ліку найкаштоўная навуковая літаратура ў Літве 18 ст. З варштатаў акадэмічнай друкарні выходзіла першая газета гістарычнай Літвы — “Kuryer Litewski”. \n\nПасля ліквідацыі Ордэну іезуітаў (1773) друкарня адышла да Віленскага ўніверсітэта, які ў 1805 годзе прадаў яе выдаўцу Юзэфу Завадскаму. Апроч іншага тут друкаваліся газеты “Dziennik Wileński”, “Pamiętnik Towarzystwa Liekarskiego Wileńskiego”, а ў 1822 годзе ўбачыў свет першы зборнік Адама Міцкевіча “Ballady i romanse”. Пра гэта сёння нагадвае мемарыяльная дошка (1999). \n\nСледам за Завадскім тут гаспадарыў выдавец Мікалай Глюксберг (да сярэдзіны 19 ст.), у якога друкаваліся гістарычны часопіс Юзафа Крашэўскага “Atheneum“ і альманах Адама Кіркора “Teka Wileńska”.\n\nЦяпер двухпавярховы дом займаюць памяшканні бібліятэк Віленскага ўніверсітэту.",
      "en": "Адрас: Šv. Jono, 4.\n\nУ першай палове 17 ст. Мікалай Хрыстафор Радзівіл Сіротка перанёс сюды з Берасця друкарню езуіцкай акадэміі , якая была адной з найбуйнейшых у Рэчы Паспалітай. Паміж 1633 і 1752 гг. тут выдавалася ад 10 да 25 выданняў штогод, у тым ліку найкаштоўная навуковая літаратура ў Літве 18 ст. З варштатаў акадэмічнай друкарні выходзіла першая газета гістарычнай Літвы — “Kuryer Litewski”. \n\nПасля ліквідацыі Ордэну іезуітаў (1773) друкарня адышла да Віленскага ўніверсітэта, які ў 1805 годзе прадаў яе выдаўцу Юзэфу Завадскаму. Апроч іншага тут друкаваліся газеты “Dziennik Wileński”, “Pamiętnik Towarzystwa Liekarskiego Wileńskiego”, а ў 1822 годзе ўбачыў свет першы зборнік Адама Міцкевіча “Ballady i romanse”. Пра гэта сёння нагадвае мемарыяльная дошка (1999). \n\nСледам за Завадскім тут гаспадарыў выдавец Мікалай Глюксберг (да сярэдзіны 19 ст.), у якога друкаваліся гістарычны часопіс Юзафа Крашэўскага “Atheneum“ і альманах Адама Кіркора “Teka Wileńska”.\n\nЦяпер двухпавярховы дом займаюць памяшканні бібліятэк Віленскага ўніверсітэту."
    },
