      "by": "Адрас: Šv. Ignoto, 4.\n \nБудучы ў Вільні, Адам Мальдзіс з Уладзімірам Караткевічам любілі зайсці ў бар \"Bociu\" на рагу вуліц Святога Ігната і Татарскай.\n\nАднак выпіць чарку ў любімым антуражы класіка цяпер не ўдасца. Ужо даўно на месцы бара іншая кавярня.",
      "ru": "Адрас: Šv. Ignoto, 4.\n \nБудучы ў Вільні, Адам Мальдзіс з Уладзімірам Караткевічам любілі зайсці ў бар \"Bociu\" на рагу вуліц Святога Ігната і Татарскай.\n\nАднак выпіць чарку ў любімым антуражы класіка цяпер не ўдасца. Ужо даўно на месцы бара іншая кавярня.",
