      "en": "Адрас: Vilniaus, 37.\n\nЗ 1923 па 1926 гг. у гэтым доме можна было адшукаць лідара заходнебеларускага руху Браніслава Тарашкевіча. У левым крыле будынка ў розны час месціліся рэдакцыі радыкальных часопісаў, бюро Таварыства беларускай школы, Школьнай рады, Беларускі студэнцкі саюз. У некалькіх пакойчыках тут жылі дзеячы беларускага адраджэння: кампазітар Антон Грыневіч і мастак Язэп Драздовіч.\n\nНа фасадзе будынка прымацаваная мемарыяльная дошка з барэльефам Тарашкевіча."
