    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.68339,
      25.28897
    ],
    "description": {
      "by": "Гэты ўніверсітэцкі двор названы ў гонар Адама Міцкевіча, які ў 1815-19 гг. вучыўся спачатку на фізіка-матэматычным, а потым на гісторыка-філалагічным факультэце Віленскага ўніверсітэта.  \nПраўда, брама, што выходзіць на ўлюбёную турыстамі вуліцу (Pilies, 13), найчасцей зачынена. У двор Міцкевіча можна прайсці з двара Ўніверсітэцкай бібліятэкі (Universiteto, 3), а ў летнюю пару — і праз рэстаран «Aula» (Pilies, 11).",
      "ru": "Гэты ўніверсітэцкі двор названы ў гонар Адама Міцкевіча, які ў 1815-19 гг. вучыўся спачатку на фізіка-матэматычным, а потым на гісторыка-філалагічным факультэце Віленскага ўніверсітэта.  \nПраўда, брама, што выходзіць на ўлюбёную турыстамі вуліцу (Pilies, 13), найчасцей зачынена. У двор Міцкевіча можна прайсці з двара Ўніверсітэцкай бібліятэкі (Universiteto, 3), а ў летнюю пару — і праз рэстаран «Aula» (Pilies, 11).",
      "en": "Гэты ўніверсітэцкі двор названы ў гонар Адама Міцкевіча, які ў 1815-19 гг. вучыўся спачатку на фізіка-матэматычным, а потым на гісторыка-філалагічным факультэце Віленскага ўніверсітэта.  \nПраўда, брама, што выходзіць на ўлюбёную турыстамі вуліцу (Pilies, 13), найчасцей зачынена. У двор Міцкевіча можна прайсці з двара Ўніверсітэцкай бібліятэкі (Universiteto, 3), а ў летнюю пару — і праз рэстаран «Aula» (Pilies, 11)."
    },
