    "coordinates": [
      54.68286,
      25.28054
    ],
    "description": {
      "by": "Адрас: Liejyklos, 1.\n\nУ 1926-30 гг. у панадворку дома №1 месцілася беларуская друкарня імя Ф.Скарыны, якая належала партыі Беларуская Хрысціянская Дэмакратыя. \n\nУ гэтым жа доме знаходзілася кнігарня “Пагоня” і жыў адзін з лідараў беларускага хрысьціянска-дэмакратычнага\nруху Янка Пазняк, які рэдагаваў газету “Biełaruskaja krynica” і часопіс\n“Хрысьціянская думка”.",
      "ru": "Адрас: Liejyklos, 1.\n\nУ 1926-30 гг. у панадворку дома №1 месцілася беларуская друкарня імя Ф.Скарыны, якая належала партыі Беларуская Хрысціянская Дэмакратыя. \n\nУ гэтым жа доме знаходзілася кнігарня “Пагоня” і жыў адзін з лідараў беларускага хрысьціянска-дэмакратычнага\nруху Янка Пазняк, які рэдагаваў газету “Biełaruskaja krynica” і часопіс\n“Хрысьціянская думка”.",
      "en": "Адрас: Liejyklos, 1.\n\nУ 1926-30 гг. у панадворку дома №1 месцілася беларуская друкарня імя Ф.Скарыны, якая належала партыі Беларуская Хрысціянская Дэмакратыя. \n\nУ гэтым жа доме знаходзілася кнігарня “Пагоня” і жыў адзін з лідараў беларускага хрысьціянска-дэмакратычнага\nруху Янка Пазняк, які рэдагаваў газету “Biełaruskaja krynica” і часопіс\n“Хрысьціянская думка”."
    },
