      "by": "Адрас: Vilniaus, 32.\n\nНа месцы гэтага будынка ў пачатку 20 ст. стаяў рэстаран \"Шуман\", частым наведнікам якога быў Янка Купала. \n\nМяркуецца, што “нашаніўская” беларуская “тусоўка” магла мець з рэстарацыяй камерцыйныя сувязі.",
      "ru": "Адрас: Vilniaus, 32.\n\nНа месцы гэтага будынка ў пачатку 20 ст. стаяў рэстаран \"Шуман\", частым наведнікам якога быў Янка Купала. \n\nМяркуецца, што “нашаніўская” беларуская “тусоўка” магла мець з рэстарацыяй камерцыйныя сувязі.",
      "en": "Адрас: Vilniaus, 32.\n\nНа месцы гэтага будынка ў пачатку 20 ст. стаяў рэстаран \"Шуман\", частым наведнікам якога быў Янка Купала. \n\nМяркуецца, што “нашаніўская” беларуская “тусоўка” магла мець з рэстарацыяй камерцыйныя сувязі."
