      "en": "Адрас: Etmonų, 4.\n\nТут у прамежаш паміж 1926 і 1928 гг. месцілася рэдакцыя сатырычнага часопіса \"Маланка\", блізкага да БСРГ.  Слоган выданьня ў \"шапцы\" абвяшчаў: \"Маланка смаліць што два тыдні\". Выдаваўся раз на два тыдні. Агулам выйшла 43 нумары."
